import csv, re, glob
from collections import defaultdict

def parse_doc(path):
    t=open(path,encoding='utf-8').read().strip()
    d={}
    for part in re.split(r'[；;]', t):
        m=re.match(r'\s*([^:：\s]+)[:：\s]\s*(.*)', part)
        if not m: continue
        k=m.group(1); v=m.group(2).strip()
        d[k]=v
    # validity
    vv=d.get('有效期','')
    mm=re.search(r'第(\d+)日至第(\d+)日', vv)
    d['start']=int(mm.group(1)); d['end']=int(mm.group(2))
    d['flow']=int(d['签发流水'])
    return d

def load_roster(path):
    r={}
    for row in csv.DictReader(open(path,encoding='utf-8-sig')):
        r[row['对象']]=row['授权签发人']
    return r

roster2=load_roster('notes/签发名册_06-02.csv')
roster7=load_roster('notes/签发名册_06-07.csv')

# all signing docs
docs=defaultdict(list)  # object -> list of dict (with signing day)
for path in glob.glob('inbox/06-02/签署附件/*/*.txt'):
    d=parse_doc(path); obj=path.split('/')[-2]; d['sign_day']=2; docs[obj].append(d)
for path in glob.glob('inbox/06-07/签署附件/*/*.txt'):
    d=parse_doc(path); obj=path.split('/')[-2]; d['sign_day']=7; docs[obj].append(d)

def roster_for(day): return roster2 if day==2 else roster7

def station_on(obj, day, revoked):
    cand=[]
    for d in docs[obj]:
        if d['类别']!='正式': continue
        if d['签发人']=='员代签': continue
        if d['签发人']!=roster_for(d['sign_day']).get(obj): continue  # signer must be authorized on signing day
        if d['flow'] in revoked: continue
        if d['start']<=day<=d['end']:
            cand.append(d)
    if not cand: return None
    cand.sort(key=lambda x:(x['start'], x['flow']))
    return cand[-1]['主站']

revoked_d7={2000,2015,2025,2040}
revoked_d10={7008,7023,7048}
revoked_before=lambda day: (revoked_d7 if day>=7 else set()) | (revoked_d10 if day>=10 else set())

print("=== (A) day3 correct station vs actual ===")
actual={'P01':('HZ-A','南站'),'P02':('HZ-B','南站'),'P04':('JL-B','西湾'),'P05':('NP-A','西湾'),'P09':('QH-A','南站'),'P10':('QH-B','北仓')}
for case,(obj,st) in actual.items():
    corr=station_on(obj,3,revoked_before(3))
    print(f"{case} {obj}: correct={corr} actual={st} {'OK' if corr==st else 'DIFF'}")

print("\n=== day3 seat allocation (correct) ===")
rows=[r for r in csv.DictReader(open('inbox/06-03/设备申请.csv',encoding='utf-8-sig'))]
dev=defaultdict(dict); info={}
for r in rows:
    c=r['案号']; d=r['设备序号']; rev=int(r['修订号']); s=int(r['申请席位']); st=r['状态']
    info[c]=(int(r['优先号']),r['服务类别'])
    if d not in dev[c] or rev>dev[c][d][0]: dev[c][d]=(rev,st,s)
dem={}
for c,dd in dev.items():
    tot=0
    for d,(rev,st,s) in dd.items():
        if st!='取消': tot+=s
    dem[c]=tot
cap3={'东港':8,'西湾':9,'南站':7,'北仓':8}
stcase={'P01':'南站','P02':'南站','P03':'东港','P04':'西湾','P05':'西湾','P06':'北仓','P07':'东港','P09':'南站','P10':'北仓','P11':'北仓'}
deferred={'P08','P12'}
order=sorted([c for c in info if c not in deferred], key=lambda c:(info[c][0],c))
rem=dict(cap3); res={}
for c in order:
    st=stcase[c]; dd=dem[c]
    if rem[st]>=dd: res[c]=dd; rem[st]-=dd
    else: res[c]=0
for c in ['P01','P02','P04','P05','P09','P10']:
    print(c, 'correct_reserved',res[c])

print("\n=== (B) day11 stations/vouchers/demands for -C ===")
rowsc=[r for r in csv.DictReader(open('inbox/06-11/设备申请.csv',encoding='utf-8-sig'))]
devc=defaultdict(dict); infoc={}
for r in rowsc:
    c=r['案号']; d=r['设备序号']; rev=int(r['修订号']); s=int(r['申请席位']); st=r['状态']
    infoc[c]=(int(r['优先号']),r['服务类别'])
    if d not in devc[c] or rev>devc[c][d][0]: devc[c][d]=(rev,st,s)
demc={}
for c,dd in devc.items():
    tot=0; parts=[]
    for d,(rev,st,s) in dd.items():
        if st!='取消': tot+=s; parts.append((d,rev,s))
        else: parts.append((d,rev,'取消'))
    demc[c]=tot
cobj={'P01-C':'HZ-A','P02-C':'HZ-B','P04-C':'JL-B','P05-C':'NP-A','P09-C':'QH-A','P10-C':'QH-B','L03-C':'NP-A'}
for c in ['P01-C','P02-C','P04-C','P05-C','P09-C','P10-C','L03-C']:
    obj=cobj[c]; st=station_on(obj,11,revoked_before(11))
    print(f"{c} {obj} pri{infoc[c][0]} cat{infoc[c][1]} station(day11)={st} demand={demc[c]} devices={devc[c]}")
