for path in glob.glob('inbox/06-07/签署附件/*/*.txt'):
    d=parse_doc(path); d['sign_day']=7; docs[path.split('/')[-2]].append(d)
def station_on(obj,day):
    revoked=set()
    if day>=7: revoked|={2000,2015,2025,2040}
    if day>=10: revoked|={7008,7023,7048}
    cand=[]
